import{_ as l,l as i,o as e,c as n,v as o,p,x as r,d as s,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"电路复杂性","description":"","frontmatter":{"title":"电路复杂性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/circuit-complexity.md","filePath":"cs/circuit-complexity.md","lastUpdated":1789023840000}'),h={name:"cs/circuit-complexity.md"};function P(_,a,m,T,u,A){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="电路复杂性" tabindex="-1">电路复杂性 <a class="header-anchor" href="#电路复杂性" aria-label="Permalink to &quot;电路复杂性&quot;">​</a></h1><div class="epigraph"><p>电路族 $\\{C_n\\}$ 是非均匀计算：每个长度一张图。P/poly 包含 P，也包含不可判定的稀疏语言；下界极难。</p><footer>—— 据 Shannon；Savage；Arora and Barak 整理</footer></div><p>上一课<a href="/cs/pcp-inapproximability">PCP</a> 仍是均匀 TM。缺口是<strong>电路</strong>：有限函数的有向无环图，门是与或非。<a href="/cs/boolean-algebra">布尔代数</a> 给了门的公理；组成课有组合网。本课把族 \\(\\{C_n\\}\\)、规模、深度、P/poly 收成复杂类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均匀：一台 TM 管所有 \\(n\\)。非均匀：允许 \\(C_n\\) 随 \\(n\\) 任意换，只要 \\(|C_n|\\) 有界（如多项式）。P/poly：多项式规模电路族。\\(P\\subseteq P/poly\\)。顾问串：多项式建议，\\(P/poly=P/\\mathrm{poly}\\)。若 \\(\\mathrm{NP}\\subseteq P/poly\\) 则 PH 塌缩（Karp–Lipton），故 NPC 问题被信不在 P/poly。Shannon：大多数函数需要指数规模电路——存在性，不给出 SAT 的下界。</p><p>AC\\(^0\\)、NC：常数深度 / 多对数深度，并行直觉。Parikh / Furst–Saxe–Sipser / Razborov–Smolensky 对 AC\\(^0\\) 的奇偶下界，点名：少数成功的下界。</p><h3 id="非均匀可以「作弊」" tabindex="-1">非均匀可以「作弊」 <a class="header-anchor" href="#非均匀可以「作弊」" aria-label="Permalink to &quot;非均匀可以「作弊」&quot;">​</a></h3><p>不可判定的一元语言可有空电路或常数电路。故 P/poly 不是「可行」的同义词。均匀性（TM 输出电路描述）才回到算法。</p><p><span class="marginnote">Shannon 计电路数目。Savage 定理：时间 \\(T\\) 的 TM 变规模 \\(O(T^2)\\) 电路（Cook–Levin 表竖过来）。Arora–Barak 第 6 章。本课不证自然证明障碍全文，点名 Razborov–Rudich。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 TM 运行表得到电路：每格一个门。反之，多项式电路不自动给出均匀算法。画 P / P/poly / EXP 的包含。深度与规模是两个轴：公式是树，电路可共享子结果。</p>',11)),(e(),p(d,null,{default:r(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TM%5B%22%E5%9D%87%E5%8C%80%20TM%22%5D%20--%3E%20TAB%5B%22%E8%AE%A1%E7%AE%97%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20CK%5B%22%E7%94%B5%E8%B7%AF%20C_n%22%5D%0A%20%20ADV%5B%22%E9%A1%BE%E9%97%AE%E4%B8%B2%22%5D%20--%3E%20PPOLY%5B%22P%2Fpoly%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下界难：自然证明说，某些「建设性」的组合性质若能区分硬函数，也会击穿伪随机，从而击穿单向函数假设。故电路下界与后课密码学咬合。本课只要这句警告，避免把「门数」当成已证的 SAT 指数下界。</p><p>Savage：时间 \\(T\\) 的多带 TM 变成规模 \\(O(T^2)\\) 电路。反之，多项式电路族不必有均匀生成器。AC\\(^0\\) 奇偶下界是少数「显式函数需要超多项式规模 / 超常数深度」的定理。自然证明障碍解释其后进展慢：能区分随机函数的组合性质太强，会破坏伪随机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Razborov–Smolensky，不引入 ACC。不把机器学习的「神经网络」当电路类。后课默认：多项式电路 = P/poly；均匀 vs 非均匀要声明。下一课换参数：FPT。</p><p>非均匀允许每个 \\(n\\) 换一张电路，甚至编码不可判定的稀疏语言。均匀性（TM 输出电路描述）才回到算法。Karp–Lipton 把「NP 有多项式电路」连到 PH 塌缩，故 NPC 被信不在 \\(P/poly\\)。</p><p>上一课留下的缺口在本课收口；「电路复杂性」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>电路族是非均匀计算；P/poly 含 P，也可含不可行对象。</li><li>TM 时间给出电路规模上界；显式下界稀缺。</li><li>Karp–Lipton：NP 若在 P/poly 则 PH 塌。</li><li>后课谈均匀 vs 非均匀，先声明电路族怎么生成。</li><li>出处：Shannon；Savage；Arora and Barak。</li></ul>',9))])}const b=l(h,[["render",P]]);export{S as __pageData,b as default};
